import { useCallback, useRef, useState } from 'react'
import { MaskedField, RedactedField } from '@app/design-system/pii'
import { useAnalytics } from '@app/hooks/useAnalytics'
import type { UserProfileCardProps } from './UserProfileCard.types'

export function UserProfileCard({ profile }: UserProfileCardProps) {
  const [isRevealed, setRevealed] = useState(false)
  const revealButtonRef = useRef<HTMLButtonElement>(null)
  const { track } = useAnalytics()

  const onReveal = useCallback(() => {
    setRevealed((prev) => {
      const next = !prev
      if (next) {
        track({
          event_type: 'pii.government_id.viewed',
          actor: { id: profile.id, type: 'user' },
          action: 'reveal',
          target: { kind: 'user', id: profile.id },
        })
      }
      revealButtonRef.current?.focus()
      return next
    })
  }, [profile.id, track])

  return (
    <section aria-labelledby='upc-heading' className='bg-surface p-4 rounded-md'>
      <h2 id='upc-heading' className='text-heading-md text-default'>
        {profile.display_name}
      </h2>
      <dl className='mt-4 grid gap-2'>
        <div>
          <dt className='text-muted'>Account</dt>
          <dd><MaskedField value={profile.account_number} reveal={4} /></dd>
        </div>
        <div>
          <dt className='text-muted'>Email</dt>
          <dd><MaskedField value={profile.email} strategy='email' /></dd>
        </div>
        <div>
          <dt className='text-muted'>Government ID</dt>
          <dd>
            <RedactedField value={profile.government_id} revealed={isRevealed} />
            <button
              ref={revealButtonRef}
              type='button'
              aria-pressed={isRevealed}
              onClick={onReveal}
              className='ml-2 text-link underline'
            >
              {isRevealed ? 'Hide' : 'Reveal'}
            </button>
            <span role='status' aria-live='polite' className='sr-only'>
              {isRevealed ? 'Government ID revealed' : 'Government ID hidden'}
            </span>
          </dd>
        </div>
      </dl>
    </section>
  )
}

import type { components } from '@codegen/api'

type CodegenUser = components['schemas']['User']

export type UserProfileCardProps = {
  profile: Pick<CodegenUser, 'id' | 'display_name' | 'account_number' | 'email' | 'government_id'>
}

