import { axe } from 'jest-axe'
import { render, screen } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { UserProfileCard } from './UserProfileCard'

const profile = {
  id: 'u_1',
  display_name: 'Synthetic Person',
  account_number: '1234567890',
  email: 'synth@example.test',
  government_id: 'SYN-0000-0000',
}

describe('UserProfileCard', () => {
  it('renders masked PII by default', () => {
    render(<UserProfileCard profile={profile} />)
    expect(screen.getByRole('heading', { name: /synthetic person/i })).toBeInTheDocument()
    expect(screen.getByText(/7890/)).toBeInTheDocument()
    expect(screen.queryByText(profile.government_id)).not.toBeInTheDocument()
  })

  it('reveals government_id on click and emits analytics + retains focus', async () => {
    const user = userEvent.setup()
    render(<UserProfileCard profile={profile} />)
    const reveal = screen.getByRole('button', { name: /reveal/i })
    await user.click(reveal)
    expect(screen.getByText(profile.government_id)).toBeInTheDocument()
    expect(screen.getByRole('button', { name: /hide/i })).toHaveFocus()
  })

  it('is axe-clean', async () => {
    const { container } = render(<UserProfileCard profile={profile} />)
    expect(await axe(container)).toHaveNoViolations()
  })
})
